'use client';
import { useEffect, useRef, useState } from 'react';
import { cn } from '@/lib/utils';

export type MarkType = 'underline' | 'highlight' | 'circle';

// Hand-drawn brush marks (underline, highlighter swipe, loose circle) drawn behind or under a word.
// The stroke "paints" itself from left to right the first time it scrolls into view.
const SHAPES: Record<MarkType, { viewBox: string; paths: string[]; width: string; wrap: string; svg: string; color: string }> = {
  underline: {
    viewBox: '0 0 100 12',
    paths: ['M2 6 C 20 2, 38 9, 58 5 S 90 3, 98 6', 'M8 10 C 38 7, 66 11, 92 8'],
    width: '0.075em',
    wrap: '',
    svg: '-bottom-[0.22em] left-0 h-[0.3em] w-full',
    color: 'text-pink',
  },
  highlight: {
    viewBox: '0 0 100 40',
    paths: ['M3 20 C 30 17, 70 23, 97 19'],
    width: '0.58em',
    wrap: '',
    svg: 'bottom-[0.02em] -left-[0.12em] h-[0.78em] w-[calc(100%+0.24em)] opacity-30',
    color: 'text-pink',
  },
  circle: {
    viewBox: '0 0 100 50',
    paths: ['M64 5 C 30 1, 4 13, 5 27 C 6 41, 40 48, 70 44 C 94 40, 99 24, 90 14 C 82 6, 58 3, 40 8'],
    width: '0.06em',
    wrap: '',
    svg: '-top-[0.3em] -left-[0.3em] h-[calc(100%+0.6em)] w-[calc(100%+0.6em)]',
    color: 'text-indigo',
  },
};

export default function Mark({
  type = 'underline',
  className,
  children,
}: {
  type?: MarkType;
  className?: string;
  children: React.ReactNode;
}) {
  const ref = useRef<HTMLSpanElement>(null);
  const [shown, setShown] = useState(false);
  const s = SHAPES[type];

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const io = new IntersectionObserver(
      ([e]) => {
        if (e.isIntersecting) {
          setShown(true);
          io.disconnect();
        }
      },
      { threshold: 0.6 }
    );
    io.observe(el);
    return () => io.disconnect();
  }, []);

  return (
    <span ref={ref} className="relative isolate inline-block whitespace-nowrap">
      <span className="relative z-10">{children}</span>
      <svg
        aria-hidden
        viewBox={s.viewBox}
        preserveAspectRatio="none"
        fill="none"
        className={cn(
          'pointer-events-none absolute z-0 overflow-visible transition-[clip-path] duration-[900ms] ease-out motion-reduce:transition-none',
          s.svg,
          s.color,
          className
        )}
        style={{ clipPath: shown ? 'inset(-60% -15% -60% -15%)' : 'inset(-60% 100% -60% -15%)' }}
      >
        {s.paths.map((d) => (
          <path
            key={d}
            d={d}
            stroke="currentColor"
            strokeWidth={s.width}
            strokeLinecap="round"
            strokeLinejoin="round"
            vectorEffect="non-scaling-stroke"
          />
        ))}
      </svg>
    </span>
  );
}
